export function registerEvidenceModule(
  app: FastifyInstance,
  { db, config }: ModuleDeps,
  store: EvidenceStore = evidenceStoreFor(config.evidenceStorage),
): ModuleRegistration {
  // Uploads arrive as raw bytes: hand the request stream to the handler, which hashes and stores it after the
  // authorization checks (never buffered whole; the size limit is enforced while streaming). F-DG2-320: only routes
  // that declare `consumes: ["application/octet-stream"]` accept it (central preParsing check, re-checked here).
  app.addContentTypeParser(
    OCTET_STREAM_MEDIA_TYPE,
    restrictParserTo(OCTET_STREAM_MEDIA_TYPE, (_request, payload, done) => done(null, payload)),
  );

  // T-DG2-BE18A (F-DG2-460, defence in depth behind the shutdown wait in main.ts): once the instance is ready, remove
  // temporary objects that no live upload can still own (STALE_TEMPORARY_AGE_MS explains the age), e.g. left by a
  // crash or a SIGKILL. In the background, so readiness never waits on a large store; tracked, so a shutdown waits.
  app.addHook("onReady", async () => {
    const sweep = store
      .sweepStaleTemporaries(STALE_TEMPORARY_AGE_MS, (removed) =>
        app.log.info(
          { key: removed.key, sizeBytes: removed.sizeBytes, ageMs: removed.ageMs },
          "evidence store: stale temporary object removed",
        ),
      )
      .then(
        (result) =>
          app.log.info(
            { ...result, olderThanMs: STALE_TEMPORARY_AGE_MS },
            "evidence store: start-up sweep of stale temporary objects finished",
          ),
        (err: unknown) => app.log.warn({ err }, "evidence store: start-up sweep of stale temporary objects failed"),
      );
    void (app.hasDecorator("inFlight") ? app.inFlight.track(sweep) : sweep);
  });

  registerRegister(app, db, evidenceRegister);
  registerContentRoutes(app, db, store);
  registerReviewRoute(app, db);
  registerLinkRoutes(app, db);
  return EVIDENCE_MODULE;
}
  });
}

function registerLinkRoutes(app: FastifyInstance, db: Db): void {
  const listQuery = z.strictObject({ ...evidenceLinkListQuery.shape, cursor: cursorSchema, limit: limitSchema });

  app.get(LINKS, { config: { access: { permission: "transformation.read" } } }, async (request) => {
    const { transformationId } = parse(tParams, request.params, "params");
    const query = parseQuery(listQuery, request.query);
    await requireTransformationRead(db, principalOf(request), transformationId);
    const hash = filterHash({ recordType: query.recordType, recordId: query.recordId });
    const after = decodeCursor(query.cursor, hash, 1);
    let q = db.selectFrom("evidence_link").selectAll().where("transformation_id", "=", transformationId);
    if (query.recordType) q = q.where("record_type", "=", query.recordType);
    if (query.recordId) q = q.where("record_id", "=", query.recordId);
    if (after) q = q.where("id", "<", String(after[0]));
    const rows = await q
      .orderBy("id", "desc")
      .limit(query.limit + 1)
      .execute();
    const page = paginate(rows, query.limit, (r) => [r.id], hash);
    return { items: page.items.map(toEvidenceLink), nextCursor: page.nextCursor };
  });

  app.post(LINKS, { config: { access: { permission: "evidence.create" } } }, async (request, reply) => {
    const { transformationId } = parse(tParams, request.params, "params");
    const result = await db.transaction().execute(async (tx) => {
