  const snapshotOf = async (transformationId: string, snapshotId: string) => {
    const row = await db
      .selectFrom("report_snapshot")
      .selectAll()
      .where("id", "=", snapshotId)
      .where("transformation_id", "=", transformationId)
      .executeTakeFirst();
    if (row === undefined) throw problems.notFound();
    return row;
