      expect(pack.body.mode).toBe("snapshot");
      expect(JSON.stringify(pack.body.document)).toContain("Synthetic: pack title one");
      expect(JSON.stringify(pack.body.document)).not.toContain("Synthetic: pack title two");
    },
  );
});

